88		}
89		if _, exists := r.cargos[cid]; exists {
90			return fail(ErrAlreadyExists, cid, "货物 %s 已存在", cid)
91		}
92		r.cargos[cid] = &cargo{
93			id:          cid,
94			weight:      weight,
95			destination: dest,
96			allowMixed:  allowMixed,
97		}
98		return nil
99	}
100	
101	// Compartment 查询舱位的承重、已用重量、剩余重量与货物清单。
102	// 编号去掉首尾空白后识别；不存在时返回错误。
103	func (r *Registry) Compartment(id string) (*CompartmentView, error) {
104		r.mu.Lock()
105		defer r.mu.Unlock()
106	
107		cid := strings.TrimSpace(id)
108		if cid == "" {
109			return nil, fail(ErrInvalidID, "", "舱位编号为空")
110		}
111		comp, ok := r.compartments[cid]
112		if !ok {
113			return nil, fail(ErrNotFound, cid, "舱位 %s 不存在", cid)
114		}
115		view := compartmentView(comp)
116		return &view, nil
117	}
118	
119	// Cargo 查询货物的当前舱位或未装载状态。
120	// 编号去掉首尾空白后识别；不存在时返回错误。
121	func (r *Registry) Cargo(id string) (*CargoView, error) {
122		r.mu.Lock()
123		defer r.mu.Unlock()
124	
125		cid := strings.TrimSpace(id)
126		if cid == "" {
127			return nil, fail(ErrInvalidID, "", "货物编号为空")
128		}
129		c, ok := r.cargos[cid]
130		if !ok {
131			return nil, fail(ErrNotFound, cid, "货物 %s 不存在", cid)
132		}
133		return cargoView(c), nil
134	}
135	
